      const transferHint = (plan.search?.reason === "transfer_options_ready" || plan.search?.phase === "transfer_ready") && journeyMix ? `\u4E00\u6B21\u4E2D\u8F6C\u8303\u56F4\u5DF2\u6838\u9A8C\u5B8C\u6BD5\u5E76\u4EA4\u4ED8\uFF08${journeyMix}\uFF09\u3002\u53EF\u4EE5\u76F4\u63A5\u9009\u7528\uFF1B\u4E5F\u53EF\u4EE5\u7EE7\u7EED\u6BD4\u8F83\u4E24\u6B21\u4E2D\u8F6C\u65B9\u6848\uFF0C\u67E5\u8BE2\u4F1A\u660E\u663E\u66F4\u4E45\u3002` : plan.search?.reason === "no_options_verified" ? `\u5F53\u524D\u6388\u6743\u6DF1\u5EA6\u5185\u7684\u8303\u56F4\u5DF2\u6838\u9A8C\u5B8C\u3001\u672A\u627E\u5230\u53EF\u7528\u65B9\u6848\u2014\u2014\u8FD9\u4E0D\u7B49\u4E8E\u6CA1\u6709\u5176\u5B83\u8DEF\u7EBF\u3002\u53EF\u6388\u6743\u7EE7\u7EED\u66F4\u6DF1\u7684\u4E24\u6B21\u4E2D\u8F6C\u641C\u7D22\uFF08\u8017\u65F6\u663E\u8457\u589E\u52A0\uFF09\uFF0C\u6216\u505C\u6B62\u3002` : "";
