        next: null,
        recovery: plan.snapshot_id ? [{ command: `itpay services read-result ${se} --snapshot ${plan.snapshot_id} --json`, reason: "\u8BFB\u53D6\u540C\u4E00\u4EFB\u52A1\u5DF2\u4FDD\u5B58\u7684\u5B8C\u6574\u76EE\u5F55" }] : [{ command: `itpay services next ${se} --json`, reason: "\u8BFB\u53D6\u540C\u4E00\u4EFB\u52A1\u5F53\u524D\u72B6\u6001" }]
